-- ==============================================================================
-- PROYECTO RAÍZ URBANA 2026 — SISTEMA DE NOTIFICACIONES
-- ARCHIVO: backend-clean/database/notificaciones_sp.sql
-- MOTOR: PostgreSQL (Supabase)
-- SEGURIDAD: SECURITY INVOKER (respeta políticas RLS y contexto de ejecución)
-- ==============================================================================
-- TABLA REAL EXISTENTE EN SUPABASE (6 columnas intactas):
--   public.tb_notificacion (
--       id_notificacion INT4 PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
--       id_usuario      INT4 NOT NULL REFERENCES public.tb_usuario(id_usuario),
--       tipo            VARCHAR(30) NOT NULL,
--       mensaje         VARCHAR(255) NOT NULL,
--       leida           BOOLEAN NOT NULL DEFAULT FALSE,
--       fecha           TIMESTAMPTZ NOT NULL DEFAULT NOW()
--   )
--
-- TABLAS DEL SISTEMA UTILIZADAS (verificadas directamente en Supabase):
--   - public.tb_usuario          (id_usuario, id_rol, estado, nombres, apellidos)
--   - public.tb_roles            (id_rol, nombre, estado)
--   - public.tb_roles_permiso    (id_rol, id_permiso)
--   - public.tb_permisos         (id_permiso, nombre)
--   - public.tb_ventas           (id_venta, id_usuario, id_estado_comp)
--   - public.tb_estado_comp      (id_estado_comp, nombre)
--   - public.tb_insumos          (id_insumo, nombre, stock, stock_minimo, estado)
--   - public.tb_producto_variante(id_producto_vari, id_producto, id_color, id_talla, stock, estado)
--   - public.tb_productos        (id_producto, nombre, estado)
--   - public.tb_colores          (id_color, nombre)
--   - public.tb_tallas           (id_talla, nombre)
--   - public.tb_orden_produccion (id_orden_produccion, id_usuario)
-- ==============================================================================

-- Índices recomendados para lectura rápida y control anti-spam (no alteran columnas)
CREATE INDEX IF NOT EXISTS idx_tb_notificacion_usuario_fecha
    ON public.tb_notificacion (id_usuario, fecha DESC);

CREATE INDEX IF NOT EXISTS idx_tb_notificacion_usuario_no_leidas
    ON public.tb_notificacion (id_usuario, tipo)
    WHERE leida = FALSE;


-- ==============================================================================
-- 1. sp_crear_notificacion_usuario
-- Inserta una notificación individual para un usuario activo.
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.sp_crear_notificacion_usuario(
    p_id_usuario INT,
    p_tipo       VARCHAR,
    p_mensaje    VARCHAR
)
RETURNS INT
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_id_notificacion INT;
    v_tipo_limpio     VARCHAR(30);
    v_mensaje_limpio  VARCHAR(255);
BEGIN
    v_tipo_limpio := LEFT(BTRIM(COALESCE(p_tipo, '')), 30);
    v_mensaje_limpio := LEFT(BTRIM(COALESCE(p_mensaje, '')), 255);

    IF p_id_usuario IS NULL OR p_id_usuario <= 0 THEN
        RAISE EXCEPTION 'El ID de usuario es obligatorio y debe ser mayor que cero.'
            USING ERRCODE = '22023';
    END IF;

    IF v_tipo_limpio = '' THEN
        RAISE EXCEPTION 'El tipo de notificación es obligatorio.'
            USING ERRCODE = '22023';
    END IF;

    IF v_mensaje_limpio = '' THEN
        RAISE EXCEPTION 'El mensaje de notificación es obligatorio.'
            USING ERRCODE = '22023';
    END IF;

    -- Validar que el usuario exista y se encuentre activo
    IF NOT EXISTS (
        SELECT 1
        FROM public.tb_usuario u
        WHERE u.id_usuario = p_id_usuario
          AND LOWER(BTRIM(COALESCE(u.estado::TEXT, ''))) IN ('activo', 'true', 't', '1')
    ) THEN
        RETURN NULL;
    END IF;

    INSERT INTO public.tb_notificacion (
        id_usuario,
        tipo,
        mensaje,
        leida,
        fecha
    )
    VALUES (
        p_id_usuario,
        v_tipo_limpio,
        v_mensaje_limpio,
        FALSE,
        NOW()
    )
    RETURNING id_notificacion INTO v_id_notificacion;

    RETURN v_id_notificacion;
END;
$$;


-- ==============================================================================
-- 2. sp_notificar_por_permiso_modulo
-- Envía una notificación a TODOS los usuarios activos cuyo rol activo tenga
-- permiso/acceso al módulo indicado en tb_roles_permiso + tb_permisos.
-- NO quema nombres de roles: soporta cualquier rol actual o futuro.
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.sp_notificar_por_permiso_modulo(
    p_modulo           VARCHAR,
    p_tipo             VARCHAR,
    p_mensaje          VARCHAR,
    p_prefijo_antispam VARCHAR DEFAULT NULL
)
RETURNS INT
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_modulo_norm    TEXT := LOWER(BTRIM(COALESCE(p_modulo, '')));
    v_tipo_limpio    VARCHAR(30) := LEFT(BTRIM(COALESCE(p_tipo, '')), 30);
    v_mensaje_limpio VARCHAR(255) := LEFT(BTRIM(COALESCE(p_mensaje, '')), 255);
    v_permisos_obj   TEXT[];
    v_insertadas     INT := 0;
BEGIN
    IF v_modulo_norm = '' OR v_tipo_limpio = '' OR v_mensaje_limpio = '' THEN
        RETURN 0;
    END IF;

    -- Mapeo dinámico a los permisos reales de tb_permisos (siempre incluye 'acceso total')
    IF v_modulo_norm IN ('ventas', 'venta') THEN
        v_permisos_obj := ARRAY['ventas', 'acceso total'];
    ELSIF v_modulo_norm IN ('control de existencias', 'control_existencias', 'inventario') THEN
        v_permisos_obj := ARRAY['productos', 'insumos', 'control de existencias', 'inventario', 'acceso total'];
    ELSIF v_modulo_norm IN ('productos', 'producto') THEN
        v_permisos_obj := ARRAY['productos', 'control de existencias', 'inventario', 'acceso total'];
    ELSIF v_modulo_norm IN ('insumos', 'insumo') THEN
        v_permisos_obj := ARRAY['insumos', 'control de existencias', 'inventario', 'acceso total'];
    ELSE
        v_permisos_obj := ARRAY[v_modulo_norm, 'acceso total'];
    END IF;

    WITH destinatarios AS (
        SELECT DISTINCT u.id_usuario
        FROM public.tb_usuario AS u
        JOIN public.tb_roles AS r
            ON r.id_rol = u.id_rol
        JOIN public.tb_roles_permiso AS rp
            ON rp.id_rol = r.id_rol
        JOIN public.tb_permisos AS p
            ON p.id_permiso = rp.id_permiso
        WHERE LOWER(BTRIM(COALESCE(u.estado::TEXT, ''))) IN ('activo', 'true', 't', '1')
          AND LOWER(BTRIM(COALESCE(r.estado::TEXT, ''))) IN ('activo', 'true', 't', '1')
          AND LOWER(BTRIM(COALESCE(p.nombre, ''))) = ANY (v_permisos_obj)
    ),
    filtrados AS (
        SELECT d.id_usuario
        FROM destinatarios d
        WHERE p_prefijo_antispam IS NULL
           OR NOT EXISTS (
               SELECT 1
               FROM public.tb_notificacion n
               WHERE n.id_usuario = d.id_usuario
                 AND n.tipo = v_tipo_limpio
                 AND n.leida = FALSE
                 AND starts_with(n.mensaje, p_prefijo_antispam)
           )
    ),
    insertados AS (
        INSERT INTO public.tb_notificacion (
            id_usuario,
            tipo,
            mensaje,
            leida,
            fecha
        )
        SELECT
            f.id_usuario,
            v_tipo_limpio,
            v_mensaje_limpio,
            FALSE,
            NOW()
        FROM filtrados f
        RETURNING id_notificacion
    )
    SELECT COUNT(*)::INT INTO v_insertadas
    FROM insertados;

    RETURN COALESCE(v_insertadas, 0);
END;
$$;


-- ==============================================================================
-- 3. sp_listar_notificaciones_usuario
-- Retorna las notificaciones del usuario ordenadas por fecha DESC,
-- junto con el total de notificaciones no leídas (leida = FALSE).
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.sp_listar_notificaciones_usuario(
    p_id_usuario INT,
    p_limite     INT DEFAULT 20,
    p_offset     INT DEFAULT 0
)
RETURNS TABLE (
    id_notificacion INT,
    id_usuario      INT,
    tipo            VARCHAR,
    mensaje         VARCHAR,
    leida           BOOLEAN,
    fecha           TIMESTAMPTZ,
    total_no_leidas BIGINT
)
LANGUAGE sql
STABLE
SECURITY INVOKER
AS $$
    WITH conteo AS (
        SELECT COUNT(*)::BIGINT AS no_leidas
        FROM public.tb_notificacion
        WHERE id_usuario = p_id_usuario
          AND leida = FALSE
    )
    SELECT
        n.id_notificacion,
        n.id_usuario,
        n.tipo,
        n.mensaje,
        n.leida,
        n.fecha,
        c.no_leidas AS total_no_leidas
    FROM public.tb_notificacion n
    CROSS JOIN conteo c
    WHERE n.id_usuario = p_id_usuario
    ORDER BY n.fecha DESC, n.id_notificacion DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limite, 20), 100))
    OFFSET GREATEST(0, COALESCE(p_offset, 0));
$$;


-- ==============================================================================
-- 4. sp_marcar_notificacion_leida
-- Marca una notificación específica como leída validando propiedad del usuario.
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.sp_marcar_notificacion_leida(
    p_id_notificacion INT,
    p_id_usuario      INT
)
RETURNS TABLE (
    id_notificacion INT,
    id_usuario      INT,
    tipo            VARCHAR,
    mensaje         VARCHAR,
    leida           BOOLEAN,
    fecha           TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    UPDATE public.tb_notificacion AS n
    SET leida = TRUE
    WHERE n.id_notificacion = p_id_notificacion
      AND n.id_usuario = p_id_usuario
    RETURNING
        n.id_notificacion,
        n.id_usuario,
        n.tipo,
        n.mensaje,
        n.leida,
        n.fecha;
END;
$$;


-- ==============================================================================
-- 5. sp_marcar_todas_notificaciones_leidas
-- Marca todas las notificaciones pendientes del usuario como leídas.
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.sp_marcar_todas_notificaciones_leidas(
    p_id_usuario INT
)
RETURNS INT
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_actualizadas INT := 0;
BEGIN
    UPDATE public.tb_notificacion
    SET leida = TRUE
    WHERE id_usuario = p_id_usuario
      AND leida = FALSE;

    GET DIAGNOSTICS v_actualizadas = ROW_COUNT;
    RETURN COALESCE(v_actualizadas, 0);
END;
$$;


-- ==============================================================================
-- 6. FUNCIONES TRIGGER PARA LOS 4 EVENTOS DEL SISTEMA
-- ==============================================================================

-- EVENTOS 1 y 3: Ventas (public.tb_ventas)
CREATE OR REPLACE FUNCTION public.fn_trg_notif_ventas()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_estado_nombre TEXT;
    v_estado_norm   TEXT;
BEGIN
    SELECT ec.nombre
    INTO v_estado_nombre
    FROM public.tb_estado_comp ec
    WHERE ec.id_estado_comp = NEW.id_estado_comp;

    v_estado_nombre := COALESCE(NULLIF(BTRIM(v_estado_nombre), ''), 'Pendiente');
    v_estado_norm := LOWER(v_estado_nombre);

    -- EVENTO 1: Nueva venta pendiente por confirmar pago
    IF TG_OP = 'INSERT' THEN
        IF v_estado_norm LIKE '%pendient%'
           OR v_estado_norm LIKE '%confirm%'
           OR NEW.id_estado_comp = 2 THEN
            PERFORM public.sp_notificar_por_permiso_modulo(
                'Ventas',
                'pago_pendiente',
                'Nueva venta #' || NEW.id_venta || ' pendiente por confirmar pago.'
            );
        END IF;

        RETURN NEW;
    END IF;

    -- EVENTO 3: Cambio de estado en pedido/compra del cliente
    IF TG_OP = 'UPDATE' AND NEW.id_estado_comp IS DISTINCT FROM OLD.id_estado_comp THEN
        IF NEW.id_usuario IS NOT NULL THEN
            PERFORM public.sp_crear_notificacion_usuario(
                NEW.id_usuario,
                'estado_pedido',
                'Tu pedido #' || NEW.id_venta || ' ha cambiado de estado a: ' || v_estado_nombre || '.'
            );
        END IF;

        IF v_estado_norm LIKE '%pendient%' OR v_estado_norm LIKE '%confirm%' THEN
            PERFORM public.sp_notificar_por_permiso_modulo(
                'Ventas',
                'pago_pendiente',
                'Nueva venta #' || NEW.id_venta || ' pendiente por confirmar pago.'
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


-- EVENTO 2: Asignación a Producción (public.tb_orden_produccion)
CREATE OR REPLACE FUNCTION public.fn_trg_notif_asignacion_produccion()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_new_json       JSONB := to_jsonb(NEW);
    v_old_json       JSONB := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
    v_id_usuario_new INT;
    v_id_usuario_old INT;
    v_id_orden       INT;
BEGIN
    v_id_usuario_new := NULLIF(v_new_json->>'id_usuario', '')::INT;
    v_id_usuario_old := NULLIF(v_old_json->>'id_usuario', '')::INT;

    v_id_orden := COALESCE(
        NULLIF(v_new_json->>'id_orden_produccion', '')::INT,
        NULLIF(v_new_json->>'id_orden_prod', '')::INT,
        NULLIF(v_new_json->>'id_produccion', '')::INT,
        0
    );

    IF v_id_usuario_new IS NOT NULL AND (
        TG_OP = 'INSERT' OR v_id_usuario_new IS DISTINCT FROM v_id_usuario_old
    ) THEN
        PERFORM public.sp_crear_notificacion_usuario(
            v_id_usuario_new,
            'asignacion_produccion',
            'Has sido asignado a la orden de producción #' || v_id_orden || '.'
        );
    END IF;

    RETURN NEW;
END;
$$;


-- EVENTO 4A: Alerta de Stock Bajo en Insumos (public.tb_insumos)
CREATE OR REPLACE FUNCTION public.fn_trg_notif_stock_bajo_insumo()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_stock_minimo INT := COALESCE(NEW.stock_minimo, 0);
    v_prefijo      VARCHAR;
    v_mensaje      VARCHAR;
BEGIN
    IF NEW.stock IS DISTINCT FROM OLD.stock
       AND LOWER(BTRIM(COALESCE(NEW.estado::TEXT, 'activo'))) IN ('activo', 'true', 't', '1')
       AND NEW.stock <= v_stock_minimo
       AND NEW.stock < COALESCE(OLD.stock, NEW.stock + 1) THEN

        v_prefijo := 'Stock bajo en insumo: ' || NEW.nombre || '.';
        v_mensaje := LEFT(
            v_prefijo || ' Quedan ' || NEW.stock || ' unidades (mínimo: ' || v_stock_minimo || ').',
            255
        );

        PERFORM public.sp_notificar_por_permiso_modulo(
            'Insumos',
            'stock_bajo',
            v_mensaje,
            v_prefijo
        );
    END IF;

    RETURN NEW;
END;
$$;


-- EVENTO 4B: Alerta de Stock Bajo en Productos / Variantes (public.tb_producto_variante)
CREATE OR REPLACE FUNCTION public.fn_trg_notif_stock_bajo_producto_variante()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_umbral_fijo    CONSTANT INT := 3;
    v_nombre_prod    TEXT;
    v_prod_activo    BOOLEAN;
    v_color          TEXT;
    v_talla          TEXT;
    v_variante_txt   TEXT := '';
    v_prefijo        VARCHAR;
    v_mensaje        VARCHAR;
BEGIN
    IF NEW.stock IS DISTINCT FROM OLD.stock
       AND COALESCE(NEW.estado, TRUE) = TRUE
       AND NEW.stock <= v_umbral_fijo
       AND NEW.stock < COALESCE(OLD.stock, NEW.stock + 1) THEN

        SELECT p.nombre, COALESCE(p.estado, TRUE)
        INTO v_nombre_prod, v_prod_activo
        FROM public.tb_productos p
        WHERE p.id_producto = NEW.id_producto;

        IF v_nombre_prod IS NULL OR v_prod_activo = FALSE THEN
            RETURN NEW;
        END IF;

        SELECT c.nombre INTO v_color
        FROM public.tb_colores c
        WHERE c.id_color = NEW.id_color;

        SELECT t.nombre INTO v_talla
        FROM public.tb_tallas t
        WHERE t.id_talla = NEW.id_talla;

        v_color := NULLIF(BTRIM(COALESCE(v_color, '')), '');
        v_talla := NULLIF(BTRIM(COALESCE(v_talla, '')), '');

        IF LOWER(COALESCE(v_color, '')) = 'no aplica' THEN v_color := NULL; END IF;
        IF LOWER(COALESCE(v_talla, '')) = 'no aplica' THEN v_talla := NULL; END IF;

        IF v_color IS NOT NULL AND v_talla IS NOT NULL THEN
            v_variante_txt := ' (' || v_color || ' / ' || v_talla || ')';
        ELSIF v_color IS NOT NULL THEN
            v_variante_txt := ' (' || v_color || ')';
        ELSIF v_talla IS NOT NULL THEN
            v_variante_txt := ' (' || v_talla || ')';
        END IF;

        v_prefijo := 'Stock bajo en producto: ' || v_nombre_prod || v_variante_txt || '.';
        v_mensaje := LEFT(
            v_prefijo || ' Quedan ' || NEW.stock || ' unidades.',
            255
        );

        PERFORM public.sp_notificar_por_permiso_modulo(
            'Productos',
            'stock_bajo',
            v_mensaje,
            v_prefijo
        );
    END IF;

    RETURN NEW;
END;
$$;


-- ==============================================================================
-- 7. REGISTRO DE TRIGGERS SOBRE LAS TABLAS REALES DEL SISTEMA
-- ==============================================================================

DROP TRIGGER IF EXISTS trg_notif_ventas ON public.tb_ventas;
CREATE TRIGGER trg_notif_ventas
AFTER INSERT OR UPDATE OF id_estado_comp
ON public.tb_ventas
FOR EACH ROW
EXECUTE FUNCTION public.fn_trg_notif_ventas();

DROP TRIGGER IF EXISTS trg_notif_stock_bajo_insumo ON public.tb_insumos;
CREATE TRIGGER trg_notif_stock_bajo_insumo
AFTER UPDATE OF stock
ON public.tb_insumos
FOR EACH ROW
EXECUTE FUNCTION public.fn_trg_notif_stock_bajo_insumo();

DROP TRIGGER IF EXISTS trg_notif_stock_bajo_producto_variante ON public.tb_producto_variante;
CREATE TRIGGER trg_notif_stock_bajo_producto_variante
AFTER UPDATE OF stock
ON public.tb_producto_variante
FOR EACH ROW
EXECUTE FUNCTION public.fn_trg_notif_stock_bajo_producto_variante();

DROP TRIGGER IF EXISTS trg_notif_asignacion_produccion ON public.tb_orden_produccion;
CREATE TRIGGER trg_notif_asignacion_produccion
AFTER INSERT OR UPDATE OF id_usuario
ON public.tb_orden_produccion
FOR EACH ROW
EXECUTE FUNCTION public.fn_trg_notif_asignacion_produccion();
